'use client';

import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { CalendarCheck, Save } from 'lucide-react';

export default function AttendancePage() {
    const [subjects, setSubjects] = useState<any[]>([]);
    const [selectedSubject, setSelectedSubject] = useState('');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [session, setSession] = useState('morning');
    const [students] = useState([
        { id: 'student-a-001', name: 'Alpha Student', roll: 'CS001' },
    ]);
    const [statuses, setStatuses] = useState<Record<string, string>>({});
    const [saved, setSaved] = useState(false);

    useEffect(() => {
        const load = async () => {
            try {
                const res = await api.get<any[]>('/api/admin/subjects');
                if (res.success) setSubjects(res.data);
            } catch (e) { }
        };
        load();
        // Init all students as present
        const init: Record<string, string> = {};
        students.forEach(s => init[s.id] = 'present');
        setStatuses(init);
    }, []);

    const handleSubmit = async () => {
        try {
            const records = Object.entries(statuses).map(([student_id, status]) => ({
                student_id, status,
            }));
            await api.post('/api/faculty/attendance/mark', {
                subject_id: selectedSubject,
                date, session, records,
            });
            setSaved(true);
            setTimeout(() => setSaved(false), 3000);
        } catch (e) { }
    };

    return (
        <div>
            <h1 style={{ fontSize: 24, fontWeight: 700, color: '#142B34', fontFamily: 'Poppins', marginBottom: 8 }}>
                Mark Attendance
            </h1>
            <p style={{ fontSize: 14, color: '#5a6a72', marginBottom: 24 }}>Record student attendance for a session</p>

            <div className="card" style={{ marginBottom: 24, padding: 28 }}>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 16, marginBottom: 24 }}>
                    <div className="form-group">
                        <label>Subject</label>
                        <select value={selectedSubject} onChange={(e) => setSelectedSubject(e.target.value)}>
                            <option value="">Select subject</option>
                            {subjects.map(s => <option key={s.id} value={s.id}>{s.name} ({s.code})</option>)}
                        </select>
                    </div>
                    <div className="form-group">
                        <label>Date</label>
                        <input type="date" value={date} onChange={(e) => setDate(e.target.value)} />
                    </div>
                    <div className="form-group">
                        <label>Session</label>
                        <select value={session} onChange={(e) => setSession(e.target.value)}>
                            <option value="morning">Morning</option>
                            <option value="afternoon">Afternoon</option>
                        </select>
                    </div>
                </div>

                <div className="table-container" style={{ marginBottom: 20 }}>
                    <table>
                        <thead>
                            <tr>
                                <th>Roll No</th>
                                <th>Name</th>
                                <th>Status</th>
                            </tr>
                        </thead>
                        <tbody>
                            {students.map(s => (
                                <tr key={s.id}>
                                    <td>{s.roll}</td>
                                    <td style={{ fontWeight: 600 }}>{s.name}</td>
                                    <td>
                                        <div style={{ display: 'flex', gap: 8 }}>
                                            {['present', 'absent', 'od'].map(st => (
                                                <button key={st} onClick={() => setStatuses({ ...statuses, [s.id]: st })}
                                                    style={{
                                                        padding: '4px 16px', borderRadius: 6, fontSize: 13, fontWeight: 600,
                                                        border: 'none', cursor: 'pointer', textTransform: 'uppercase',
                                                        background: statuses[s.id] === st
                                                            ? (st === 'present' ? '#d1fae5' : st === 'absent' ? '#fee2e2' : '#dbeafe')
                                                            : '#f3f4f6',
                                                        color: statuses[s.id] === st
                                                            ? (st === 'present' ? '#065f46' : st === 'absent' ? '#991b1b' : '#1e40af')
                                                            : '#8a9aa2',
                                                    }}>
                                                    {st}
                                                </button>
                                            ))}
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>

                <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
                    <button className="btn-primary" onClick={handleSubmit} disabled={!selectedSubject}>
                        <Save size={16} /> Save Attendance
                    </button>
                    {saved && <span style={{ color: '#059669', fontSize: 14, fontWeight: 600 }}>✓ Attendance saved successfully!</span>}
                </div>
            </div>
        </div>
    );
}
